 evidence={'build':'1002p1','account_rows':rows,'studies':studies,'clock_audit':read(DATA/'clock-audit.json'),'options_units_audit':read(DATA/'combined-rounding-audit.json'),'scope':'BTC-only development; incomplete original COT vintages; delta-equivalent option holdings, not new option trades or causal impact; no live execution'};(D/'btc-position-evidence.json').write_bytes(canonical(evidence))
